5	// work view (helpers/work.mjs). Repo-state rules and settings diagnostics run in
6	// check_the_world.mjs, which this file shares no code with (only the scope-blind
7	// mechanism helpers). The Stop hook runs this; CI runs the world runner.
8	//   --transcript PATH   the session transcript — conversation rules self-skip without it
9	//   --changed / --base REF / --root DIR   as in check_the_world.mjs
10	import { buildContext } from './helpers/repo-context.mjs';
11	import { discoverPacks } from '../pack_loader/pack-registry.mjs';
12	import { runActivePackRules } from './run-active-pack-rules.mjs';
